namespace Nami.Collector.Storage.Generators;

internal static class StorageDefaultsSource
{
    public const string Source = """
                                 // <auto-generated/>
                                 // Storage defaults owned by the storage generator.

                                 #nullable enable

                                 namespace Nami.Collector.Storage;

                                 /// <summary>Generator-owned storage defaults for the collector process.</summary>
                                 internal static class StorageDefaults
                                 {
                                     /// <summary>Default DuckDB database file when NAMI_DATA_PATH is not configured.</summary>
                                     public const string DatabaseFileName = "nami.duckdb";
                                 }
                                 """;
}

internal static class DuckDbAttributeSource
{
    public const string Source = """
                                 // <auto-generated/>
                                 // DuckDB code generation attributes

                                 #nullable enable

                                 namespace Nami.Collector.Storage;

                                 /// <summary>
                                 /// Marks a partial type for DuckDB helper generation.
                                 /// Generator creates schema, parameter, reader, and eligible appender helpers.
                                 /// </summary>
                                 [System.AttributeUsage(System.AttributeTargets.Class, AllowMultiple = false)]
                                 internal sealed class DuckDbTableAttribute : System.Attribute
                                 {
                                     /// <summary>Table name in DuckDB.</summary>
                                     public string TableName { get; }

                                     /// <summary>Optional ON CONFLICT clause for upsert behavior.</summary>
                                     public string? OnConflict { get; set; }

                                     /// <summary>
                                     /// Generate a reusable-row appender for an append-only table whose writes need no
                                     /// conflict clause, returned key, compare-and-swap predicate, or per-row result.
                                     /// </summary>
                                     public bool AppenderEligible { get; set; }

                                     /// <summary>
                                     /// Marks storage that can be discarded and reconstructed from authoritative data.
                                     /// Derived tables are reset automatically when their generated schema identity changes.
                                     /// </summary>
                                     public bool Derived { get; set; }

                                     /// <summary>Generate a bounded-memory Apache Arrow reader for bulk scans.</summary>
                                     public bool ArrowEligible { get; set; }

                                     /// <summary>
                                     /// Semicolon-separated index column groups. Use CLR property names, e.g. "ProjectId;ProjectId,TraceId".
                                     /// </summary>
                                     public string Indexes { get; set; } = "";

                                     /// <summary>
                                     /// Semicolon-separated unique-index column groups. Uses the same CLR property-name syntax as Indexes.
                                     /// </summary>
                                     public string UniqueIndexes { get; set; } = "";

                                     /// <summary>
                                     /// Semicolon-separated named parameter sets for explicit SQL operations.
                                     /// Each set uses "Name:Property,Property" syntax. The generator owns the
                                     /// physical column names, CLR parameter types, and positional binder order.
                                     /// </summary>
                                     public string ParameterSets { get; set; } = "";

                                     public DuckDbTableAttribute(string tableName) => TableName = tableName;
                                 }

                                 /// <summary>
                                 /// Marks a property for DuckDB column mapping.
                                 /// Property names are converted to snake_case.
                                 /// </summary>
                                 [System.AttributeUsage(System.AttributeTargets.Property, AllowMultiple = false)]
                                 internal sealed class DuckDbColumnAttribute : System.Attribute
                                 {
                                     /// <summary>Set true to exclude from INSERT (e.g., auto-generated columns).</summary>
                                     public bool ExcludeFromInsert { get; set; }

                                     /// <summary>Optional DuckDB SQL type override for generated CREATE TABLE DDL.</summary>
                                     public string? SqlType { get; set; }

                                     /// <summary>Optional SQL default expression for generated CREATE TABLE DDL.</summary>
                                     public string? DefaultSql { get; set; }

                                     /// <summary>Primary-key order for generated CREATE TABLE DDL. Leave -1 for non-key columns.</summary>
                                     public int PrimaryKeyOrdinal { get; set; } = -1;

                                 }
                                 """;
}
